using System;using System.Linq;using System.Collections.Generic;using System.Windows.Forms;using BeamScheduleFormatter;
class TrussSupportTests {
 static System.Reflection.BindingFlags flags2(){return System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;}
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,double tol,string why){Check(Math.Abs(a-b)<=tol,why+" ("+a+" vs "+b+")");}
 const string Table="Node\tL/C\tHorizontal Fx kN\tVertical Fy kN\tHorizontal Fz kN\tMoment Mx kN-m\tMoment My kN-m\tMoment Mz kN-m\n1\t101 1.2D+1.6L\t5.2\t40\t0\t0\t0\t0\n\t102 0.9D+1.6W\t-8\t-25\t3\t0\t0\t0\n2\t101 1.2D+1.6L\t-5.2\t42\t0\t0\t0\t0\n";
 [STAThread] /* the two test cases (formerly preset buttons of the sheet, taken from sample drawings; the buttons were removed, the data stays here) */
 static void Apply(TrussSupportForm form,Dictionary<string,string> values,string size,string cols,int grade,string chord){var fl=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
  var inputs=(Dictionary<string,Control>)typeof(DesignSheetForm).GetField("Inputs",fl).GetValue(form);var restoring=typeof(DesignSheetForm).GetField("Restoring",fl);restoring.SetValue(form,true);
  try{foreach(var v in values)inputs[v.Key].Text=v.Value;((ComboBox)inputs["AnchorSize"]).SelectedItem=AnchorBolts.Powersteel.First(a=>a.Name.StartsWith(size)).Name;((ComboBox)inputs["BoltColumns"]).SelectedItem=cols;((ComboBox)inputs["AnchorType"]).SelectedIndex=1;((ComboBox)inputs["AnchorGrade"]).SelectedIndex=grade;((ComboBox)inputs["PlateConnection"]).SelectedIndex=0;((ComboBox)inputs["Chord"]).SelectedItem=chord;((ComboBox)inputs["ChordAngles"]).SelectedIndex=0;inputs["ChordWeldLength"].Text="";}
  finally{restoring.SetValue(form,false);}typeof(TrussSupportForm).GetMethod("ApplyAnchorSize",fl).Invoke(form,null);}
 static void Typical(TrussSupportForm form){Apply(form,new Dictionary<string,string>{{"PlateN","250"},{"PlateB","300"},{"PlateT","16"},{"SupportB","300"},{"SupportN","300"},{"BoltS2","200"},{"BoltS1","90"},{"Hef","240"},{"HookEh","80"},{"GussetT","6"},{"GussetL","320"},{"GussetH","250"},{"Futa","400"},{"Fya","250"}},"Ø3/4\" x 12\"","2",0,"L50x50x5mm (PNS)");}
 static void Truss2(TrussSupportForm form){Apply(form,new Dictionary<string,string>{{"PlateN","1000"},{"PlateB","350"},{"PlateT","20"},{"PlateFy","248"},{"SupportN","1100"},{"SupportB","500"},{"SupportDepth","700"},{"BoltS2","250"},{"BoltS1","225"},{"Hef","350"},{"HookEh","80"},{"Futa","825"},{"Fya","635"},{"GussetL","1000"},{"GussetH","400"}},"Ø3/4\" x 18\" (hook 4\", thread 7\")","5",1,"L75x75x6mm (PNS)");}
 static void Main(){
  string unit;var rows=TrussSupport.Reactions(Table,out unit);Check(rows.Count==3&&rows[1].Node=="1"&&rows[1].Case.StartsWith("102")&&rows[1].Fy==-25&&unit=="kN","STAAD Support Reactions table with the node carried down");
  var kip=TrussSupport.Reactions("Node\tL/C\tFx kip\tFy kip\tFz kip\n1\t1\t1\t2\t0\n",out unit);Near(kip[0].Fy,2*4.4482216,1e-6,"kip converted to kN");
  var spaced=TrussSupport.Reactions("Node L/C Horizontal Fx kN Vertical Fy kN Horizontal Fz kN\n1 101 4 30 1\n",out unit);Check(spaced.Count==1&&spaced[0].Fy==30&&spaced[0].Fz==1,"space separated headings with units");
  var typed=TrussSupport.Reactions("1 1 0 30 0\n2 1 0 -10 2\n",out unit);Check(typed.Count==2&&typed[1].Fz==2,"typed rows without headings");
  var input=new TrussSupportInput{PlateB=250,PlateN=300,PlateT=12,SupportB=300,SupportN=400,SupportDepth=400,Fc=21,BoltDia=20,BoltColumns=1,BoltS2=150,Hef=300,Angle=SteelCatalog.Profiles.First(p=>p.Kind=="Angle bar"&&p.H==50&&p.B==50),Angles=2};
  var notes=new List<string>();var res=TrussSupport.Check(input,rows,notes);Func<string,SupportCheck> c=name=>res.First(x=>x.Name==name);
  Near(c("Anchor steel - tension").Capacity,.75*245*400*2/1000,1e-6,"φNsa = 0.75 n Ase futa");Near(c("Concrete bearing").Capacity,.65*.85*21*75000*1.2/1000,1e-6,"φPp with √(A2/A1) = 1.2");
  double nb=10*Math.Sqrt(21)*Math.Pow(300,1.5)/1000;Near(c("Concrete breakout - tension").Capacity,.70*(120000.0/810000)*.75*nb,1e-6,"φNcbg = 0.70 ANc/ANco ψed Nb");
  Check(c("Anchor steel - tension").Demand==25&&c("Anchor steel - tension").Case.StartsWith("102"),"uplift row governs the anchor tension");Check(c("Concrete bearing").Demand==42&&c("Concrete bearing").Node=="2","largest downward reaction governs bearing");
  Near(c("Anchor steel - shear").Demand,Math.Sqrt(64+9),1e-9,"shear = √(Fx² + Fz²)");Check(c("Concrete breakout - tension").Ratio>1&&!c("Concrete breakout - tension").Ok,"breakout at a 75 mm edge is NG for 25 kN uplift");
  var r1=c("Tension-shear interaction");Check(r1.Ratio>0,"interaction ratio");
  var ap=TrussSupport.AngleProperties(input.Angle);Check(ap[0]>0&&ap[1]>0&&ap[1]<input.Angle.B,"angle area and centroid");
  bool bad=false;try{TrussSupport.Check(new TrussSupportInput{PlateB=400,PlateN=300,PlateT=12,SupportB=300,SupportN=400,Angle=input.Angle},rows,new List<string>());}catch(Exception){bad=true;}Check(bad,"a plate wider than the support is refused");
  /* other members at the joint and a gusset longer than the plate (Detail 6) */
  var detail=new TrussSupportInput{PlateB=300,PlateN=250,PlateT=16,SupportB=300,SupportN=300,SupportDepth=400,Fc=21,BoltDia=20,BoltColumns=2,BoltS1=90,BoltS2=200,Hef=240,Headed=false,HookEh=80,GussetT=6,GussetL=320,Angle=input.Angle,Angles=2,Others=new List<JointMember>{new JointMember{Name="Diagonal",Angles=2,Angle=input.Angle,Force=-35,HeelWeld=100,ToeWeld=60,Weld=6},new JointMember{Name="Post",Angles=1,Angle=input.Angle,Force=12}}};
  var dn=new List<string>();var dr=TrussSupport.Check(detail,rows,dn);Check(dn.Any(x=>x.Contains("welded to the plate over 250 mm")),"a gusset longer than the plate is welded over the plate length");Check(dr.Any(x=>x.Name=="Diagonal: Whitmore buckling"&&x.Demand==35)&&dr.Any(x=>x.Name=="Post: tension rupture"&&x.Demand==12)&&!dr.Any(x=>x.Name=="Post: Whitmore buckling"),"each other member is checked for its own force (compression: buckling, tension: rupture)");
  Near(dr.First(x=>x.Name=="Gusset shear yielding").Capacity,.6*248*6*250/1000,1e-9,"gusset shear over the plate length");
  /* bottom chord welded to the plate, anchors outside the angles (owner: "naka install sa labas ng angle bar naka weld yung angle bar sa baseplate") */
  var chordIn=new TrussSupportInput{PlateB=300,PlateN=250,PlateT=16,SupportB=300,SupportN=300,SupportDepth=400,Fc=21,BoltDia=20,BoltColumns=2,BoltS1=90,BoltS2=200,Hef=240,Headed=false,HookEh=80,GussetT=6,GussetL=320,Angle=input.Angle,Angles=2,ChordOnPlate=true,Chord=SteelCatalog.Find("L50x50x5mm (PNS)"),ChordAngles=2,ChordWeld=6};
  Near(chordIn.Footprint,2*50+6,1e-9,"chord footprint 2B + tg");var cn=new List<string>();var cr=TrussSupport.Check(chordIn,rows,cn);Check(cr.Any(x=>x.Name=="Chord-to-plate welds")&&!cr.Any(x=>x.Name=="Gusset-to-plate welds"),"chord-to-plate welds replace the gusset welds");
  Near(cr.First(x=>x.Name=="Chord-to-plate welds").Capacity,.75*.6*482*.707*6/1000,1e-9,"chord weld capacity per mm");var leg=cr.First(x=>x.Name=="Chord leg bending - uplift");Near(leg.Demand,Math.Sqrt(4*(25*1000/2.0*(50-5))/(.9*248*250)),1e-6,"chord leg bending under 25 kN uplift");Check(leg.Capacity==5,"leg thickness");
  Near(cr.First(x=>x.Name=="Plate thickness - bearing").Demand,(300-106)/2.0*Math.Sqrt(2*42*1000/(.9*248*300*250)),1e-6,"bearing cantilever from the angle toes: (B - footprint)/2");
  bool tight=false;try{chordIn.BoltS2=130;TrussSupport.Check(chordIn,rows,new List<string>());}catch(Exception ex){tight=ex.Message.Contains("not clear of the chord");}Check(tight,"anchors that hit the angle legs are refused");
  AccessCodes.Granted=true;using(var form=new TrussSupportForm()){Typical(form);var ti=form.Input();Check(ti.PlateN==250&&ti.PlateB==300&&ti.PlateT==16&&Math.Abs(ti.BoltDia-19.05)<1e-9&&ti.BoltName.StartsWith("Ø3/4\" x 12\"")&&ti.BoltColumns==2&&!ti.Headed&&ti.GussetL==320&&ti.GussetT==6&&Math.Abs(ti.HookEh-101.6)<.5&&Math.Abs(ti.Hef-(12*25.4-(25+16+Math.Max(3,.15*19.05)+19.05+6)-19.05))<1,"Typical detail fills Detail 6 with a Powersteel 3/4 x 12 anchor bolt");
   /* interactive model: dragging and typing on the drawing change the inputs (owner: "Gawin mong interactive ang input may model") */
   form.StartPosition=FormStartPosition.Manual;form.ClientSize=new System.Drawing.Size(1400,900);form.Show();var pages=(TabControl)typeof(DesignSheetForm).GetField("Pages",flags2()).GetValue(form);pages.SelectedIndex=1;for(int k=0;k<20;k++)Application.DoEvents();
   var sketch=(TrussSupportSketch)typeof(TrussSupportForm).GetField("sketch",flags2()).GetValue(form);sketch.Refresh();Application.DoEvents();var handles=(System.Collections.IList)typeof(TrussSupportSketch).GetField("handles",flags2()).GetValue(sketch);Check(handles.Count>8,"model has drag handles");
   Func<object,string> key=h=>(string)h.GetType().GetField("Key").GetValue(h);Func<object,System.Drawing.RectangleF> area=h=>(System.Drawing.RectangleF)h.GetType().GetField("Area").GetValue(h);Action<string,object[]> call=(name,args)=>typeof(TrussSupportSketch).GetMethod(name,flags2()).Invoke(sketch,args);
   Func<string,System.Drawing.PointF> centre=k2=>{foreach(var h in handles)if(key(h)==k2){var a=area(h);return new System.Drawing.PointF(a.Left+a.Width/2,a.Top+a.Height/2);}throw new Exception("no handle "+k2);};
   Action<System.Drawing.PointF,int,int> drag=(start,dx,dy)=>{call("OnMouseDown",new object[]{new MouseEventArgs(MouseButtons.Left,1,(int)start.X,(int)start.Y,0)});call("OnMouseMove",new object[]{new MouseEventArgs(MouseButtons.Left,0,(int)start.X+dx,(int)start.Y+dy,0)});call("OnMouseUp",new object[]{new MouseEventArgs(MouseButtons.Left,1,(int)start.X+dx,(int)start.Y+dy,0)});sketch.Refresh();Application.DoEvents();handles=(System.Collections.IList)typeof(TrussSupportSketch).GetField("handles",flags2()).GetValue(sketch);};
   var ins=(Dictionary<string,Control>)typeof(DesignSheetForm).GetField("Inputs",flags2()).GetValue(form);var right=handles.Cast<object>().Where(h=>key(h)=="PlateN").Select(area).OrderByDescending(a=>a.Left).First();drag(new System.Drawing.PointF(right.Left+right.Width/2,right.Top+right.Height/2),12,0);double n2=double.Parse(ins["PlateN"].Text,System.Globalization.CultureInfo.InvariantCulture);Check(n2>250&&n2%5==0,"dragging the plate edge widens N in 5 mm steps ("+n2+"; handle "+right+", sketch "+sketch.Size+", planScale "+typeof(TrussSupportSketch).GetField("planScale",flags2()).GetValue(sketch)+", centre "+typeof(TrussSupportSketch).GetField("planCenter",flags2()).GetValue(sketch)+", handles "+string.Join(" ",handles.Cast<object>().Select(h=>key(h)+area(h)))+")");
   var bolt=handles.Cast<object>().Where(h=>key(h)=="Bolt").Select(area).OrderBy(a=>a.Top).First();drag(new System.Drawing.PointF(bolt.Left+bolt.Width/2,bolt.Top+bolt.Height/2),0,-10);Check(double.Parse(ins["BoltS2"].Text,System.Globalization.CultureInfo.InvariantCulture)>200,"dragging an anchor across widens the gauge");
   double hef0=double.Parse(ins["Hef"].Text,System.Globalization.CultureInfo.InvariantCulture);drag(centre("Hef"),0,15);Check(double.Parse(ins["Hef"].Text,System.Globalization.CultureInfo.InvariantCulture)>hef0,"dragging the anchor tip deepens hef");
   var labels=(System.Collections.IList)typeof(TrussSupportSketch).GetField("labels",flags2()).GetValue(sketch);object gl=labels.Cast<object>().First(l=>(string)l.GetType().GetField("Key").GetValue(l)=="GussetL");var ga=(System.Drawing.RectangleF)gl.GetType().GetField("Area").GetValue(gl);call("OnMouseDoubleClick",new object[]{new MouseEventArgs(MouseButtons.Left,2,(int)(ga.Left+2),(int)(ga.Top+2),0)});var editor=(TextBox)typeof(TrussSupportSketch).GetField("editor",flags2()).GetValue(sketch);editor.Text="400";typeof(TextBox).GetMethod("OnKeyDown",flags2()).Invoke(editor,new object[]{new KeyEventArgs(Keys.Enter)});Check(ins["GussetL"].Text=="400","double-clicking a dimension types its value");
   Truss2(form);var t2=form.Input();Check(t2.PlateN==1000&&t2.PlateB==350&&t2.PlateT==20&&t2.BoltColumns==5&&t2.BoltS1==225&&t2.BoltS2==250&&t2.Hef>=350&&t2.Futa==825&&t2.Fya==635&&!t2.Headed&&t2.BoltName.Contains("18")&&Math.Abs(t2.ThreadLength-7*25.4)<1e-9,"Truss 2 anchorage preset: 10 - Powersteel 3/4 x 18 L bolts, embedment at least 350 mm");
   var r2=TrussSupport.Check(t2,rows,new List<string>());Near(r2.First(x=>x.Name=="Anchor steel - tension").Capacity,.75*215.5*825*10/1000,1e-6,"10 anchors, 3/4 in UNC stress area, A325 futa 825");Check(r2.Any(x=>x.Name=="Anchor thread length"&&x.Ok),"thread length check");Near(AnchorBolts.StressArea(25.4),391,1e-9,"1 in stress area");Check(AnchorBolts.Powersteel.Count==36&&AnchorBolts.Powersteel.Count(a=>a.Dia=="3/4")==14,"Powersteel table");
   ((ComboBox)ins["AnchorGrade"]).SelectedIndex=2;Check(ins["Futa"].Text=="517"&&ins["Fya"].Text=="380","choosing the anchor material fills futa and fya");
   form.Hide();}
  AccessCodes.Granted=true;using(var form=new TrussSupportForm()){var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;var inputs=(Dictionary<string,Control>)typeof(DesignSheetForm).GetField("Inputs",flags).GetValue(form);inputs["Reactions"].Text=Table;inputs["Nodes"].Text="2";
   string report=form.CurrentReport();Check(report.Contains("## 04  CHECKS")&&report.Contains("Concrete bearing")&&report.Contains("not an engineer's approval"),"report");string unit2;Check(form.Rows(out unit2).All(r=>r.Node=="2"),"node filter");
   string xml=form.Snapshot();using(var again=new TrussSupportForm()){again.Restore(xml);var i2=(Dictionary<string,Control>)typeof(DesignSheetForm).GetField("Inputs",flags).GetValue(again);Check(i2["Reactions"].Text.Replace("\r","")==Table.Replace("\r","")&&i2["Nodes"].Text=="2","sheet saves the reactions");}}
  Console.WriteLine("PASS: "+checks+" truss support plate, anchor, weld and angle checks");}
